def eulerian_num(n, m):
    # Base case: If m is 0, the Eulerian number is 0 for any n > 1
    if m == 0:
        return 0 if n > 1 else 1
    # Base case: If n equals m, the Eulerian number is always 1
    elif n == m:
        return 1
    # Recursive case: Calculate Eulerian number using the recursive formula
    else:
        return ((n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m))

