def set_left_most_unset_bit(n):
    # Find the first unset bit from the right and set it
    # by creating a mask that isolates the first unset bit
    if (n & (n + 1)) == 0:
        return n
    mask = (~n) & (n + 1)
    while (mask & 1) == 0:
        mask >>= 1
    return n | (mask << 1)
